  "implementation": "def solve(case):
    lines = case.get("lines", [])
    import re
    patterns = {
        "thought": re.compile(r'^Thought:\s*(.*)$', re.DOTALL),
        "action": re.compile(r'^Action:\s*(.*)$', re.DOTALL),
        "action_input": re.compile(r'^Action Input:\s*(.*)$', re.DOTALL),
        "observation": re.compile(r'^Observation:\s*(.*)$', re.DOTALL),
        "final": re.compile(r'^Final:\s*(.*)$', re.DOTALL)
    }
    state = "start"
    trajectory = []
    error_line = None
    valid = True
    for i, line in enumerate(lines, start=1):
        matched = False
        for rec_type, pat in patterns.items():
            m = pat.match(line)
            if m:
                content = m.group(1).strip()
                allowed = False
                if state == "start":
                    allowed = rec_type in ("thought", "final")
                elif state == "after_thought":
                    allowed = rec_type in ("action", "action_input", "final")
                elif state == "after_action":
                    allowed = rec_type in ("action_input", "observation")
                elif state == "after_action_input":
                    allowed = rec_type == "observation"
                elif state == "after_observation":
                    allowed = rec_type in ("thought", "final")
                elif state == "after_final":
                    allowed = False
                if not allowed:
                    error_line = i
                    valid = False
                    break
                trajectory.append({"type": rec_type, "content": content})
                if rec_type == "thought":
                    state = "after_thought"
                elif rec_type == "action":
                    state = "after_action"
                elif rec_type == "action_input":
                    state = "after_action_input"
                elif rec_type == "observation":
                    state = "after_observation"
                elif rec_type == "final":
                    state = "after_final"
                matched = True
                break
        if not matched:
            error_line = i
            valid = False
            break
        if error_line is not None:
            break
    if error_line is None:
        if not lines:
            pass
        elif state not in ("after_observation", "after_final"):
            error_line = len(lines)
            valid = False
            if trajectory:
                trajectory.pop()
    return {"error_line": error_line, "trajectory": trajectory, "valid": valid}
